<?php require_once '../config/helpers.php';require_admin();$rows=$pdo->query('SELECT c.*,COUNT(b.id) booking_count FROM customers c LEFT JOIN bookings b ON b.customer_id=c.id GROUP BY c.id ORDER BY c.created_at DESC')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>Customers</title></head><body><div class="admin-layout"><?php include '_nav.php'; ?><section class="admin-main"><h1>Customers</h1><div class="panel table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Bookings</th><th>Registered</th></tr></thead><tbody><?php foreach($rows as $c): ?><tr><td><?= e($c['full_name']) ?></td><td><?= e($c['email']) ?></td><td><a href="tel:<?= e($c['phone']) ?>"><?= e($c['phone']) ?></a></td><td><?= (int)$c['booking_count'] ?></td><td><?= e($c['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></body></html>
